CREATE VIEW [dbo].[ApparecchiInstallati2] AS  
SELECT 'NSL' AS Categoria ,'New Slot' AS Tipo, move.locale AS IdLocale,2 AS TipoOggetto,'NSL' AS TipoOggettoDesc,move.dedicato AS CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 1 AS TM, move.idmove, NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, Dedicati.DataCreazione, dedicati.fornitore, dedicati.costruttore, dedicati.IdMagazzino, 0 AS Ordinamento, 0 AS OrdinamentoCategoria FROM move,dedicati WHERE dedicati.iddedicato=move.dedicato AND dedicati.partipologiamonopoli=1 AND move.dedicato>0 UNION SELECT 'C7A' AS Categoria ,'Gioco' AS Tipo, move.locale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,move.dedicato AS CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, ParTipologiaMonopoli AS TM, move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA,  Dedicati.DataCreazione, dedicati.fornitore, dedicati.costruttore, dedicati.IdMagazzino, 1 AS Ordinamento, 1 AS OrdinamentoCategoria FROM move,dedicati WHERE dedicati.iddedicato=move.dedicato AND dedicati.partipologiamonopoli=2 AND move.dedicato>0 UNION SELECT 'C7C' AS Categoria ,'Gioco' AS Tipo, move.locale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,move.dedicato AS CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, ParTipologiaMonopoli AS TM, move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, Dedicati.DataCreazione, dedicati.fornitore, dedicati.costruttore, dedicati.IdMagazzino, 1 AS Ordinamento, 2 AS OrdinamentoCategoria FROM move,dedicati WHERE dedicati.iddedicato=move.dedicato AND dedicati.partipologiamonopoli=4 AND move.dedicato>0 UNION SELECT 'MEC' AS Categoria ,'Gioco' AS Tipo, move.locale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,move.dedicato AS CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, ParTipologiaMonopoli AS TM, move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, Dedicati.DataCreazione, dedicati.fornitore, dedicati.costruttore, dedicati.IdMagazzino, 1 AS Ordinamento, 3 AS OrdinamentoCategoria FROM move,dedicati WHERE dedicati.iddedicato=move.dedicato AND (dedicati.partipologiamonopoli>4 OR dedicati.partipologiamonopoli IS NULL) AND move.dedicato>0 UNION SELECT 'NSL' AS Categoria, 'Mobile' AS Tipo, move.locale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,move.mobile AS CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, ParTipologiaMonopoli AS TM, move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, mobili.DataCreazione, mobili.fornitore, mobili.costruttore, mobili.IdMagazzino, 2 AS Ordinamento, 0 AS OrdinamentoCategoria FROM move,mobili WHERE mobili.idmobile=move.mobile AND move.mobile>0 AND ParTipologiaMonopoli=1 UNION SELECT 'C7A' AS Categoria, 'Mobile' AS Tipo, move.locale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,move.mobile AS CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, ParTipologiaMonopoli AS TM, move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, mobili.DataCreazione, mobili.fornitore, mobili.costruttore, mobili.IdMagazzino, 2 AS Ordinamento, 1 AS OrdinamentoCategoria FROM move,mobili WHERE mobili.idmobile=move.mobile AND move.mobile>0 AND ParTipologiaMonopoli=2 UNION SELECT 'C7C' AS Categoria, 'Mobile' AS Tipo, move.locale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,move.mobile AS CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, ParTipologiaMonopoli AS TM, move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, mobili.DataCreazione, mobili.fornitore, mobili.costruttore, mobili.IdMagazzino, 2 AS Ordinamento, 2 AS OrdinamentoCategoria FROM move,mobili WHERE mobili.idmobile=move.mobile AND move.mobile>0 AND ParTipologiaMonopoli=4 UNION SELECT 'MEC' AS Categoria, 'Mobile' AS Tipo, move.locale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,move.mobile AS CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, ParTipologiaMonopoli AS TM, move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, mobili.DataCreazione, mobili.fornitore, mobili.costruttore, mobili.IdMagazzino, 2 AS Ordinamento, 3 AS OrdinamentoCategoria FROM move,mobili WHERE mobili.idmobile=move.mobile AND move.mobile>0 AND  (mobili.partipologiamonopoli>4 OR mobili.partipologiamonopoli IS NULL) UNION SELECT 'SCH' AS Categoria, 'Scheda' AS Tipo, FirstMove.locale AS IdLocale,1 AS TipoOggetto,'SCH' AS TipoOggettoDesc, FirstMove.scheda AS CodiceOggetto,schede.prop AS Proprieta,schede.agente AS Associato, schede.matricola,schede.nome as Modello, '' AS identificativo,'' AS nullaosta, NULL AS TM ,FirstMove.idmove,NULL AS IdStorico, (SELECT SecondMove.mobile FROM move AS SecondMove WHERE SecondMove.idmove=FirstMove.movimentorif) as IdPadre, FirstMove.DataCambio AS DataDa, NULL AS DataA, schede.DataCreazione, schede.fornitore, schede.costruttore, schede.IdMagazzino, 3 AS Ordinamento, 4 AS OrdinamentoCategoria FROM move AS FirstMove,schede WHERE schede.idscheda=FirstMove.scheda AND FirstMove.scheda>0 UNION SELECT 'DIS' AS Categoria, 'Distributore' AS Tipo, move.locale AS IdLocale,15 AS TipoOggetto,'DIS' AS TipoOggettoDesc, move.distributore AS CodiceOggetto,distribut.prop AS Proprieta,distribut.agente AS Associato, distribut.matricola,distribut.nome as Modello, '' AS identificativo,'' AS nullaosta,  NULL AS TM,move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, distribut.DataCreazione, distribut.fornitore, distribut.costruttore, distribut.IdMagazzino, 4 AS Ordinamento, 5 AS OrdinamentoCategoria FROM move,distribut WHERE distribut.iddistributore=move.distributore AND move.distributore>0 UNION SELECT 'ACC' AS Categoria, 'Accessorio' AS Tipo, move.locale AS IdLocale,3 AS TipoOggetto,'ACC' AS TipoOggettoDesc, move.Accessorio AS CodiceOggetto,Accessori.prop AS Proprieta,'' AS Associato, Accessori.matricola,Accessori.nome as Modello, '' AS identificativo,'' AS nullaosta,  NULL AS TM,move.idmove,NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, Accessori.DataCostruzione AS DataCreazione, Accessori.fornitore, Accessori.costruttore, Accessori.IdMagazzino, 5 AS Ordinamento, 6 AS OrdinamentoCategoria FROM move,Accessori WHERE Accessori.idAccessorio=move.Accessorio AND move.Accessorio>0
GO
